const PILLARS = [
  {
    cls: 'p1', title: 'AEO (Answer Engine Optimization)',
    text: 'Help your brand appear in answers from ChatGPT, Gemini, Perplexity, Copilot, and other AI engines. Track the prompts that matter and see how people find your brand.',
    icon: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="8" /><circle cx="12" cy="12" r="3" /></svg>,
  },
  {
    cls: 'p2', title: 'GEO (Generative Engine Optimization)',
    text: 'Improve your content for AI and generative search. Make it easier for generative engines to understand your content and use your brand as a source.',
    icon: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 3v18M3 12h18M6 6l12 12M18 6L6 18" /></svg>,
  },
  {
    cls: 'p3', title: 'SEO (Search Engine Optimization)',
    text: 'Improve your Google visibility with technical audits, on-page fixes, and competitor tracking.',
    icon: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="7" /><path d="M21 21l-4.3-4.3" /></svg>,
  },
  {
    cls: 'p4', title: 'Digital Marketing & Social Automation',
    text: 'Plan your content and manage social media automation across Instagram, Facebook, LinkedIn, Google Business Profile, and YouTube.',
    icon: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><rect x="3" y="4" width="18" height="17" rx="2" /><path d="M3 9h18M8 2v4M16 2v4" /></svg>,
  },
];

export default function Product() {
  return (
    <section id="product">
      <div className="wrap">
        <div className="head">
          <span className="eyebrow">Our platform</span>
          <h2>One platform. Every way you get found.</h2>
          <p>The platform brings AEO, GEO, SEO, and digital marketing together in one place.</p>
        </div>
        <div className="pillars-grid">
          {PILLARS.map((p, i) => (
            <div className={`pillar ${p.cls}`} key={p.title + i}>
              <div className="icon">{p.icon}</div>
              <h3>{p.title}</h3>
              <p>{p.text}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
